ALTER TABLE `users` ADD COLUMN `team` varchar(100) NOT NULL DEFAULT 'Genel' AFTER `role`, ADD COLUMN `last_login_at` timestamp NULL AFTER `status`, ADD INDEX `idx_users_team` (`team`);
CREATE TABLE IF NOT EXISTS `user_invites` (`id` int AUTO_INCREMENT PRIMARY KEY,`email` varchar(190) NOT NULL,`display_name` varchar(190) NOT NULL,`role` varchar(32) NOT NULL,`team` varchar(100) NOT NULL DEFAULT 'Genel',`token_hash` varchar(64) NOT NULL UNIQUE,`status` varchar(24) NOT NULL DEFAULT 'pending',`invited_by` varchar(190) NOT NULL,`expires_at` timestamp NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX `idx_user_invite_email` (`email`),INDEX `idx_user_invite_status` (`status`));
CREATE TABLE IF NOT EXISTS `user_activities` (`id` int AUTO_INCREMENT PRIMARY KEY,`user_id` int NULL,`actor_email` varchar(190) NOT NULL,`action` varchar(64) NOT NULL,`description` varchar(255) NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX `idx_user_activity_created` (`created_at`),INDEX `idx_user_activity_user` (`user_id`),CONSTRAINT `fk_user_activity_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL);
